WITH base AS (SELECT id, order_id, carrier, cost, status, DAYOFWEEK(delivered_date) AS delivered_date_dayofweek, COALESCE(carrier, 'DIRECT') AS resolved_carrier FROM shipments WHERE shipped_date > TO_DATE('2023-12-22') AND carrier <> 'Flash') SELECT CASE WHEN cost >= 96 THEN 'PREMIUM' ELSE 'STANDARD' END AS cost_tier, status, SUM(CASE WHEN carrier = 'Flash' THEN delivered_date_dayofweek ELSE 0 END) AS flash_delivered_date_dayofweek, ROUND(AVG(cost), 2) AS avg_cost, COUNT(DISTINCT carrier) AS distinct_carriers, GROUPING(CASE WHEN cost >= 96 THEN 'PREMIUM' ELSE 'STANDARD' END) AS grouping_id FROM base GROUP BY GROUPING SETS ((CASE WHEN cost >= 96 THEN 'PREMIUM' ELSE 'STANDARD' END, status), (CASE WHEN cost >= 96 THEN 'PREMIUM' ELSE 'STANDARD' END), ())
